  "status": "implemented",
  "summary": "Modified SnapshotFormatter.boundLine to preserve complete UTF-16 surrogate pairs when truncating a line to MAX_LINE_CHARS.",
  "edits": [
    {
      "path": "src/main/java/dev/atmcompanion/state/SnapshotFormatter.java",
      "operation": "replace",
      "find": "return safe.length() <= MAX_LINE_CHARS ? safe : safe.substring(0, MAX_LINE_CHARS - 3) + \"...\";",
      "replace": "int length = safe.length();\nif (length <= MAX_LINE_CHARS) {\n    return safe;\n}\n\nint truncateIndex = MAX_LINE_CHARS - 3;\nwhile (truncateIndex > 0 && Character.isHighSurrogate(safe.charAt(truncateIndex - 1))) {\n    truncateIndex--;\n}\n\nreturn safe.substring(0, truncateIndex) + \"...\";"
    }
  ],
